-- Keystone: one lender, its dealers, their customers. One PostgreSQL database
-- that six Apps read (test/fixtures/apps/keystone/SUITE.md is the contract).
--
-- Ownership decides the shape. /leads is a tenant App (each dealer a tenant,
-- the lender its platform realm), and a tenant App's rules are the strictest
-- any App here puts on the tables (docs/tenant-apps.md), so the whole schema
-- is written to them; the row-policy and open Apps are satisfied along the way.
--
-- * Every table has one owner. TENANT: a dealer's own rows, owned through
--   `dealer_id text`, the id of the dealer's `dealer` row (the tenancy
--   profile). GLOBAL: `program`, read by every dealer, owned by none.
--   PLATFORM: the lender's own — everything else.
-- * A tenant-owned table keys on one opaque text id, and every other unique
--   index on it includes `dealer_id`: two dealers may both hold lead LD-1001.
-- * A tenant row reaches another tenant row through a composite key,
--   `(dealer_id, x_id) -> x(dealer_id, id)`, so it cannot point out of its
--   dealer, and again through the single column, which is what a related list
--   walks. It reaches a platform table only through `dealer_id`, and a global
--   one freely. So the lender's judgment cannot sit on a dealer's row as a key:
--   who underwrote and who decided live on the platform-owned
--   `underwriting_file`; the dealer's `loan_application` carries the outcome.
-- * A platform row may point at a tenant row (a loan at its application).
-- * Row policies (/dealer, /customer, /marketplace) filter on a table's own
--   columns, never a path (src/shared/rowScope.ts:14-15), so every row a
--   customer may see carries `customer_id` itself, kept honest the same way:
--   `(customer_id, loan_id) -> loan(customer_id, id)`.
-- * Platform tables key on integer identities. Readable references
--   (`KA-104001`, `KL-200001`, `LD-1001`) are what people quote; a vehicle's
--   id is its public slug (`2024-toyota-rav4-xle-st1042`), because a tenant
--   table cannot carry a second globally unique column.
-- * Money is numeric(12,2) US dollars; rates are percent points (7.490 is
--   7.49%); a day is `date`, a moment `timestamp` (UTC).
-- * `version` is on every row a command changes, for its revision guard.
-- * A row a command inserts gets its key from a default.

-- ================================================================ platform: the lender

CREATE TABLE lender_user (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name text NOT NULL,
  email text NOT NULL UNIQUE,
  -- The account this person signs in with (per App today; SUITE.md, "One account").
  account_id text UNIQUE,
  role text NOT NULL CHECK (role IN ('admin', 'credit_manager', 'underwriter', 'funder', 'servicing', 'relationship_manager')),
  title text NOT NULL,
  active boolean NOT NULL DEFAULT true,
  hired_on date NOT NULL
);

-- The tenancy profile: one row per dealer, and `id` is the tenant id.
CREATE TABLE dealer (
  id text PRIMARY KEY CHECK (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  name text NOT NULL,
  legal_name text NOT NULL,
  kind text NOT NULL CHECK (kind IN ('franchise', 'independent')),
  franchise_make text,
  status text NOT NULL CHECK (status IN ('prospect', 'active', 'on_hold', 'terminated')),
  tier text NOT NULL CHECK (tier IN ('gold', 'silver', 'bronze')),
  street text NOT NULL,
  city text NOT NULL,
  state text NOT NULL CHECK (state ~ '^[A-Z]{2}$'),
  zip text NOT NULL CHECK (zip ~ '^[0-9]{5}$'),
  phone text NOT NULL,
  email text NOT NULL,
  relationship_manager_id integer REFERENCES lender_user(id),
  -- The dealer's share of the finance charge, paid at funding.
  reserve_pct numeric(5,2) NOT NULL CHECK (reserve_pct BETWEEN 0 AND 5),
  monthly_goal integer NOT NULL CHECK (monthly_goal >= 0),
  joined_on date NOT NULL,
  on_hold_reason text,
  -- The public intake address /leads' apply form is published under
  -- (`/leads/form/apply?via=…`). 128 random bits the lender writes and only the
  -- server resolves: never seeded, so a public repository cannot predict one.
  intake_address text UNIQUE,
  version integer NOT NULL DEFAULT 0,
  CHECK ((kind = 'franchise') = (franchise_make IS NOT NULL)),
  CHECK ((status = 'on_hold') = (on_hold_reason IS NOT NULL))
);

CREATE TABLE dealer_visit (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  dealer_id text NOT NULL REFERENCES dealer(id),
  lender_user_id integer NOT NULL REFERENCES lender_user(id),
  happened_on date NOT NULL,
  kind text NOT NULL CHECK (kind IN ('visit', 'call', 'review', 'training')),
  summary text NOT NULL,
  next_step text
);

-- ================================================================ global: the rate sheet

CREATE TABLE program (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code text NOT NULL UNIQUE,
  name text NOT NULL,
  tier text NOT NULL CHECK (tier IN ('super_prime', 'prime', 'near_prime', 'subprime')),
  min_score integer NOT NULL CHECK (min_score BETWEEN 300 AND 850),
  max_ltv_pct numeric(5,1) NOT NULL CHECK (max_ltv_pct > 0),
  max_term integer NOT NULL CHECK (max_term BETWEEN 12 AND 96),
  max_vehicle_age integer NOT NULL CHECK (max_vehicle_age >= 0),
  max_mileage integer NOT NULL CHECK (max_mileage > 0),
  base_apr numeric(6,3) NOT NULL CHECK (base_apr >= 0),
  max_amount numeric(12,2) NOT NULL CHECK (max_amount > 0),
  -- On the marketplace's rate card; the rest are dealer-only.
  advertised boolean NOT NULL DEFAULT false,
  active boolean NOT NULL DEFAULT true,
  description text NOT NULL
);

-- ================================================================ tenant: a dealer's own

-- The dealer's white-labeled website: edited in /dealer, drawn by /site.
CREATE TABLE dealer_site (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  dealer_id text NOT NULL UNIQUE REFERENCES dealer(id),
  published boolean NOT NULL DEFAULT false,
  headline text NOT NULL,
  tagline text,
  about text,
  brand_color text NOT NULL CHECK (brand_color ~ '^#[0-9a-f]{6}$'),
  accent_color text NOT NULL CHECK (accent_color ~ '^#[0-9a-f]{6}$'),
  -- Two or three letters the mark is drawn from while logos cannot upload.
  logo_text text NOT NULL CHECK (length(logo_text) BETWEEN 1 AND 3),
  custom_domain text,
  show_prices boolean NOT NULL DEFAULT true,
  contact_email text NOT NULL,
  contact_phone text NOT NULL,
  hours text NOT NULL,
  published_on date,
  version integer NOT NULL DEFAULT 0,
  UNIQUE (dealer_id, id),
  CHECK (published = (published_on IS NOT NULL))
);

-- The dealer's people as business data: who a lead is assigned to. Who may
-- sign in to /leads is a tenant membership in the tenant store, not this row;
-- `account_id` binds the Leads sign-in. Dealer settings has a separate auth
-- store, so its sign-in uses dealer_account_id instead of overwriting it.
CREATE TABLE dealer_user (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  dealer_id text NOT NULL REFERENCES dealer(id),
  name text NOT NULL,
  email text NOT NULL,
  phone text,
  account_id text,
  dealer_account_id text,
  role text NOT NULL CHECK (role IN ('owner', 'sales_manager', 'finance_manager', 'salesperson', 'viewer')),
  status text NOT NULL CHECK (status IN ('invited', 'active', 'deactivated')),
  invited_on date NOT NULL,
  joined_on date,
  version integer NOT NULL DEFAULT 0,
  UNIQUE (dealer_id, id),
  UNIQUE (dealer_id, email),
  UNIQUE (dealer_id, account_id),
  UNIQUE (dealer_id, dealer_account_id),
  CHECK ((status = 'invited') = (joined_on IS NULL))
);

CREATE TABLE vehicle (
  -- The public slug: /marketplace/vehicles/2024-toyota-rav4-xle-st1042.
  id text PRIMARY KEY CHECK (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  dealer_id text NOT NULL REFERENCES dealer(id),
  stock_number text NOT NULL,
  vin text NOT NULL CHECK (vin ~ '^[A-HJ-NPR-Z0-9]{17}$'),
  year integer NOT NULL CHECK (year BETWEEN 2010 AND 2028),
  make text NOT NULL,
  model text NOT NULL,
  trim text NOT NULL,
  body text NOT NULL CHECK (body IN ('sedan', 'suv', 'truck', 'coupe', 'hatchback', 'wagon', 'van')),
  fuel text NOT NULL CHECK (fuel IN ('gas', 'hybrid', 'electric', 'diesel')),
  drivetrain text NOT NULL CHECK (drivetrain IN ('fwd', 'rwd', 'awd', '4wd')),
  mileage integer NOT NULL CHECK (mileage >= 0),
  exterior_color text NOT NULL,
  interior_color text NOT NULL,
  condition text NOT NULL CHECK (condition IN ('new', 'used', 'certified')),
  -- What the dealer paid: the dealer's own figure, never public, never the lender's.
  cost numeric(12,2) NOT NULL CHECK (cost > 0),
  list_price numeric(12,2) NOT NULL CHECK (list_price > 0),
  -- A marketplace card's "$412/mo": the dealer's advertised payment at 72 months.
  est_payment numeric(12,2),
  featured boolean NOT NULL DEFAULT false,
  status text NOT NULL CHECK (status IN ('in_stock', 'listed', 'pending', 'sold', 'wholesale')),
  received_on date NOT NULL,
  listed_on date,
  sold_on date,
  description text,
  -- One feature a line: a vehicle page draws them as a list.
  features text,
  version integer NOT NULL DEFAULT 0,
  UNIQUE (dealer_id, id),
  UNIQUE (dealer_id, stock_number),
  UNIQUE (dealer_id, vin),
  CHECK ((status = 'sold') = (sold_on IS NOT NULL)),
  CHECK (status NOT IN ('listed', 'pending') OR listed_on IS NOT NULL)
);
CREATE INDEX vehicle_status ON vehicle (status, dealer_id);

CREATE TABLE vehicle_photo (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  dealer_id text NOT NULL REFERENCES dealer(id),
  vehicle_id text NOT NULL,
  position integer NOT NULL CHECK (position > 0),
  caption text NOT NULL,
  file_name text NOT NULL,
  content_type text NOT NULL,
  byte_size integer NOT NULL,
  data bytea NOT NULL,
  thumbnail bytea,
  UNIQUE (dealer_id, id),
  UNIQUE (dealer_id, vehicle_id, position),
  FOREIGN KEY (dealer_id, vehicle_id) REFERENCES vehicle(dealer_id, id),
  FOREIGN KEY (vehicle_id) REFERENCES vehicle(id)
);

-- A person the dealer is working. From the public apply form it starts as a
-- `draft` saved on every step (the resume columns belong to the server), and
-- becomes `new` on submit.
CREATE TABLE lead (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  dealer_id text NOT NULL REFERENCES dealer(id),
  -- The receipt a person quotes; a draft has none yet.
  reference text,
  source text NOT NULL CHECK (source IN ('website', 'marketplace', 'walk_in', 'phone', 'referral', 'third_party')),
  status text NOT NULL CHECK (status IN ('draft', 'new', 'contacted', 'desking', 'submitted', 'sold', 'lost')),
  first_name text NOT NULL,
  last_name text NOT NULL,
  email text,
  phone text,
  vehicle_id text,
  salesperson_id text,
  message text,
  -- A marketplace customer's own account (the /marketplace sign-in), so they
  -- can follow the inquiry they sent; null for everyone else.
  marketplace_account_id text,
  created_at timestamp NOT NULL,
  last_contact_at timestamp,
  next_follow_up_on date,
  lost_reason text CHECK (lost_reason IN ('bought_elsewhere', 'no_response', 'credit', 'price', 'other')),
  resume_token_hash text,
  resume_expires_at timestamptz,
  resume_progress text,
  version integer NOT NULL DEFAULT 0,
  UNIQUE (dealer_id, id),
  UNIQUE (dealer_id, reference),
  FOREIGN KEY (dealer_id, vehicle_id) REFERENCES vehicle(dealer_id, id),
  FOREIGN KEY (vehicle_id) REFERENCES vehicle(id),
  FOREIGN KEY (dealer_id, salesperson_id) REFERENCES dealer_user(dealer_id, id),
  FOREIGN KEY (salesperson_id) REFERENCES dealer_user(id),
  CHECK (email IS NOT NULL OR phone IS NOT NULL),
  CHECK ((status = 'lost') = (lost_reason IS NOT NULL)),
  CHECK (status = 'draft' OR reference IS NOT NULL)
);
CREATE INDEX lead_status ON lead (dealer_id, status);

-- Everything that happened to a lead: the timeline /leads draws.
CREATE TABLE lead_activity (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  dealer_id text NOT NULL REFERENCES dealer(id),
  lead_id text NOT NULL,
  kind text NOT NULL CHECK (kind IN ('note', 'call', 'email', 'text', 'visit', 'test_drive', 'status')),
  body text NOT NULL,
  author_id text,
  created_at timestamp NOT NULL,
  UNIQUE (dealer_id, id),
  FOREIGN KEY (dealer_id, lead_id) REFERENCES lead(dealer_id, id),
  FOREIGN KEY (lead_id) REFERENCES lead(id),
  FOREIGN KEY (dealer_id, author_id) REFERENCES dealer_user(dealer_id, id),
  FOREIGN KEY (author_id) REFERENCES dealer_user(id)
);

-- A person on a credit application, as the dealer took it down, beneath the
-- lead that collected it (so the saved form's steps may write it). A person
-- who applies at two dealers is two applicants: each dealer owns its own.
CREATE TABLE applicant (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  dealer_id text NOT NULL REFERENCES dealer(id),
  lead_id text NOT NULL,
  role text NOT NULL CHECK (role IN ('primary', 'co_applicant')),
  first_name text NOT NULL,
  last_name text NOT NULL,
  email text NOT NULL,
  phone text NOT NULL,
  date_of_birth date NOT NULL,
  ssn_last4 text NOT NULL CHECK (ssn_last4 ~ '^[0-9]{4}$'),
  street text NOT NULL,
  city text NOT NULL,
  state text NOT NULL CHECK (state ~ '^[A-Z]{2}$'),
  zip text NOT NULL CHECK (zip ~ '^[0-9]{5}$'),
  housing text NOT NULL CHECK (housing IN ('own', 'rent', 'family', 'other')),
  monthly_housing numeric(12,2) NOT NULL CHECK (monthly_housing >= 0),
  years_at_address numeric(4,1) NOT NULL CHECK (years_at_address >= 0),
  employer text,
  job_title text,
  employment_type text NOT NULL CHECK (employment_type IN ('full_time', 'part_time', 'self_employed', 'retired', 'other')),
  years_employed numeric(4,1) NOT NULL CHECK (years_employed >= 0),
  monthly_income numeric(12,2) NOT NULL CHECK (monthly_income >= 0),
  created_at timestamp NOT NULL,
  UNIQUE (dealer_id, id),
  UNIQUE (dealer_id, lead_id, role),
  FOREIGN KEY (dealer_id, lead_id) REFERENCES lead(dealer_id, id),
  FOREIGN KEY (lead_id) REFERENCES lead(id)
);

-- A deal on the desk: the numbers a finance manager structures before
-- submitting. `amount_financed` is what the lender is asked to lend.
CREATE TABLE deal (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  dealer_id text NOT NULL REFERENCES dealer(id),
  reference text NOT NULL,
  lead_id text NOT NULL,
  applicant_id text NOT NULL,
  co_applicant_id text,
  vehicle_id text NOT NULL,
  salesperson_id text,
  finance_manager_id text,
  program_id integer REFERENCES program(id),
  status text NOT NULL CHECK (status IN ('structuring', 'submitted', 'approved', 'contracted', 'funded', 'cancelled')),
  sale_price numeric(12,2) NOT NULL CHECK (sale_price > 0),
  doc_fee numeric(12,2) NOT NULL DEFAULT 0,
  tax_rate numeric(5,3) NOT NULL CHECK (tax_rate >= 0),
  sales_tax numeric(12,2) NOT NULL DEFAULT 0,
  title_fees numeric(12,2) NOT NULL DEFAULT 0,
  trade_allowance numeric(12,2) NOT NULL DEFAULT 0,
  trade_payoff numeric(12,2) NOT NULL DEFAULT 0,
  cash_down numeric(12,2) NOT NULL DEFAULT 0,
  rebate numeric(12,2) NOT NULL DEFAULT 0,
  service_contract numeric(12,2) NOT NULL DEFAULT 0,
  gap numeric(12,2) NOT NULL DEFAULT 0,
  amount_financed numeric(12,2) NOT NULL CHECK (amount_financed >= 0),
  term_months integer NOT NULL CHECK (term_months BETWEEN 12 AND 96),
  apr numeric(6,3) NOT NULL CHECK (apr >= 0),
  monthly_payment numeric(12,2) NOT NULL CHECK (monthly_payment >= 0),
  created_on date NOT NULL,
  updated_at timestamp NOT NULL,
  version integer NOT NULL DEFAULT 0,
  UNIQUE (dealer_id, id),
  UNIQUE (dealer_id, reference),
  FOREIGN KEY (dealer_id, lead_id) REFERENCES lead(dealer_id, id),
  FOREIGN KEY (lead_id) REFERENCES lead(id),
  FOREIGN KEY (dealer_id, applicant_id) REFERENCES applicant(dealer_id, id),
  FOREIGN KEY (applicant_id) REFERENCES applicant(id),
  FOREIGN KEY (dealer_id, co_applicant_id) REFERENCES applicant(dealer_id, id),
  FOREIGN KEY (co_applicant_id) REFERENCES applicant(id),
  FOREIGN KEY (dealer_id, vehicle_id) REFERENCES vehicle(dealer_id, id),
  FOREIGN KEY (vehicle_id) REFERENCES vehicle(id),
  FOREIGN KEY (dealer_id, salesperson_id) REFERENCES dealer_user(dealer_id, id),
  FOREIGN KEY (salesperson_id) REFERENCES dealer_user(id),
  FOREIGN KEY (dealer_id, finance_manager_id) REFERENCES dealer_user(dealer_id, id),
  FOREIGN KEY (finance_manager_id) REFERENCES dealer_user(id)
);

CREATE TABLE trade_in (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  dealer_id text NOT NULL REFERENCES dealer(id),
  deal_id text NOT NULL,
  vin text NOT NULL CHECK (vin ~ '^[A-HJ-NPR-Z0-9]{17}$'),
  year integer NOT NULL,
  make text NOT NULL,
  model text NOT NULL,
  mileage integer NOT NULL CHECK (mileage >= 0),
  condition text NOT NULL CHECK (condition IN ('excellent', 'good', 'fair', 'rough')),
  -- What the dealer credits the customer, and what the dealer thinks it is worth.
  allowance numeric(12,2) NOT NULL CHECK (allowance >= 0),
  acv numeric(12,2) NOT NULL CHECK (acv >= 0),
  payoff numeric(12,2) NOT NULL DEFAULT 0 CHECK (payoff >= 0),
  lienholder text,
  version integer NOT NULL DEFAULT 0,
  UNIQUE (dealer_id, id),
  FOREIGN KEY (dealer_id, deal_id) REFERENCES deal(dealer_id, id),
  FOREIGN KEY (deal_id) REFERENCES deal(id),
  CHECK ((payoff > 0) = (lienholder IS NOT NULL))
);

-- The payment grid: the structures a finance manager puts in front of a
-- customer. One is selected, and its numbers are the deal's.
CREATE TABLE deal_scenario (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  dealer_id text NOT NULL REFERENCES dealer(id),
  deal_id text NOT NULL,
  label text NOT NULL,
  term_months integer NOT NULL CHECK (term_months BETWEEN 12 AND 96),
  apr numeric(6,3) NOT NULL CHECK (apr >= 0),
  cash_down numeric(12,2) NOT NULL CHECK (cash_down >= 0),
  amount_financed numeric(12,2) NOT NULL CHECK (amount_financed >= 0),
  monthly_payment numeric(12,2) NOT NULL CHECK (monthly_payment >= 0),
  selected boolean NOT NULL DEFAULT false,
  UNIQUE (dealer_id, id),
  UNIQUE (dealer_id, deal_id, label),
  FOREIGN KEY (dealer_id, deal_id) REFERENCES deal(dealer_id, id),
  FOREIGN KEY (deal_id) REFERENCES deal(id)
);

-- The dealer's application to the lender. The outcome is written here, where
-- the dealer reads it; the lender's file is `underwriting_file`.
CREATE TABLE loan_application (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  dealer_id text NOT NULL REFERENCES dealer(id),
  reference text NOT NULL,
  deal_id text NOT NULL,
  applicant_id text NOT NULL,
  co_applicant_id text,
  vehicle_id text NOT NULL,
  program_id integer REFERENCES program(id),
  status text NOT NULL CHECK (status IN ('submitted', 'in_review', 'conditioned', 'approved', 'countered', 'declined', 'withdrawn', 'funded')),
  requested_amount numeric(12,2) NOT NULL CHECK (requested_amount > 0),
  requested_term integer NOT NULL CHECK (requested_term BETWEEN 12 AND 96),
  down_payment numeric(12,2) NOT NULL CHECK (down_payment >= 0),
  vehicle_value numeric(12,2) NOT NULL CHECK (vehicle_value > 0),
  ltv_pct numeric(6,1) NOT NULL,
  dti_pct numeric(5,1) NOT NULL,
  pti_pct numeric(5,1) NOT NULL,
  dealer_note text,
  submitted_at timestamp NOT NULL,
  decided_at timestamp,
  approved_amount numeric(12,2),
  approved_apr numeric(6,3),
  approved_term integer,
  approved_payment numeric(12,2),
  decline_reason text CHECK (decline_reason IN ('credit_history', 'debt_to_income', 'loan_to_value', 'income_unverified', 'collateral', 'program_limits')),
  withdrawn_reason text,
  version integer NOT NULL DEFAULT 0,
  UNIQUE (dealer_id, id),
  UNIQUE (dealer_id, reference),
  UNIQUE (dealer_id, deal_id),
  FOREIGN KEY (dealer_id, deal_id) REFERENCES deal(dealer_id, id),
  FOREIGN KEY (deal_id) REFERENCES deal(id),
  FOREIGN KEY (dealer_id, applicant_id) REFERENCES applicant(dealer_id, id),
  FOREIGN KEY (applicant_id) REFERENCES applicant(id),
  FOREIGN KEY (dealer_id, co_applicant_id) REFERENCES applicant(dealer_id, id),
  FOREIGN KEY (co_applicant_id) REFERENCES applicant(id),
  FOREIGN KEY (dealer_id, vehicle_id) REFERENCES vehicle(dealer_id, id),
  FOREIGN KEY (vehicle_id) REFERENCES vehicle(id),
  CHECK ((status IN ('approved', 'countered', 'declined', 'funded')) = (decided_at IS NOT NULL)),
  CHECK ((status IN ('approved', 'countered', 'funded')) = (approved_amount IS NOT NULL)),
  CHECK ((status = 'declined') = (decline_reason IS NOT NULL)),
  CHECK ((status = 'withdrawn') = (withdrawn_reason IS NOT NULL))
);
CREATE INDEX loan_application_status ON loan_application (status, submitted_at);

-- The conditions of an approval. The dealer collects them; the lender clears them.
CREATE TABLE stipulation (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  dealer_id text NOT NULL REFERENCES dealer(id),
  application_id text NOT NULL,
  kind text NOT NULL CHECK (kind IN ('proof_of_income', 'proof_of_residence', 'proof_of_insurance', 'references', 'drivers_license', 'signed_contract')),
  status text NOT NULL CHECK (status IN ('requested', 'received', 'cleared', 'waived')),
  requested_at timestamp NOT NULL,
  received_at timestamp,
  cleared_at timestamp,
  note text,
  version integer NOT NULL DEFAULT 0,
  UNIQUE (dealer_id, id),
  UNIQUE (dealer_id, application_id, kind),
  FOREIGN KEY (dealer_id, application_id) REFERENCES loan_application(dealer_id, id),
  FOREIGN KEY (application_id) REFERENCES loan_application(id)
);

-- ================================================================ platform: underwriting and funding

-- The lender's file on an application, one each: who has it, the bureau's
-- answer, who decided. A dealer's context has no schema for it.
CREATE TABLE underwriting_file (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  application_id text NOT NULL UNIQUE REFERENCES loan_application(id),
  dealer_id text NOT NULL REFERENCES dealer(id),
  underwriter_id integer REFERENCES lender_user(id),
  assigned_at timestamp,
  decided_by integer REFERENCES lender_user(id),
  bureau text NOT NULL CHECK (bureau IN ('Equifax', 'Experian', 'TransUnion')),
  score integer NOT NULL CHECK (score BETWEEN 300 AND 850),
  pulled_at timestamp NOT NULL,
  open_tradelines integer NOT NULL,
  auto_tradelines integer NOT NULL,
  revolving_utilization_pct numeric(5,1) NOT NULL,
  delinquencies_24m integer NOT NULL,
  public_records integer NOT NULL,
  inquiries_6m integer NOT NULL,
  monthly_debt numeric(12,2) NOT NULL,
  -- When the lender owes the dealer an answer.
  decision_due_at timestamp NOT NULL,
  version integer NOT NULL DEFAULT 0,
  CHECK ((underwriter_id IS NULL) = (assigned_at IS NULL))
);

CREATE TABLE underwriting_note (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  application_id text NOT NULL REFERENCES loan_application(id),
  author_id integer NOT NULL REFERENCES lender_user(id),
  created_at timestamp NOT NULL,
  body text NOT NULL
);

-- Raised by the decision clock (a job) when an answer is late.
CREATE TABLE decision_alert (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  application_id text NOT NULL REFERENCES loan_application(id),
  dealer_id text NOT NULL REFERENCES dealer(id),
  raised_at timestamp NOT NULL,
  due_at timestamp NOT NULL,
  resolved_at timestamp,
  UNIQUE (application_id, due_at)
);

-- From an approval to money at the dealer: the contract arrives, is audited, is funded.
CREATE TABLE funding (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  application_id text NOT NULL UNIQUE REFERENCES loan_application(id),
  dealer_id text NOT NULL REFERENCES dealer(id),
  status text NOT NULL CHECK (status IN ('awaiting_contract', 'in_audit', 'ready', 'funded', 'rejected')),
  contract_received_on date,
  audited_by integer REFERENCES lender_user(id),
  funded_on date,
  -- What the lender wires the dealer, and the dealer's reserve inside it.
  amount numeric(12,2) NOT NULL CHECK (amount > 0),
  dealer_reserve numeric(12,2) NOT NULL DEFAULT 0 CHECK (dealer_reserve >= 0),
  reject_reason text,
  version integer NOT NULL DEFAULT 0,
  CHECK ((status = 'funded') = (funded_on IS NOT NULL)),
  CHECK ((status = 'rejected') = (reject_reason IS NOT NULL))
);

-- An apply form the server could not place in a dealer (no address, an
-- unknown one, a dealer on hold): the lender's triage queue, saved on every
-- step as the dealer's draft lead is.
CREATE TABLE intake_submission (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  reference text UNIQUE,
  status text NOT NULL CHECK (status IN ('draft', 'open', 'followed_up', 'closed')),
  first_name text NOT NULL,
  last_name text NOT NULL,
  email text NOT NULL,
  phone text,
  street text,
  city text,
  state text,
  zip text,
  employer text,
  monthly_income numeric(12,2),
  vehicle_interest text,
  -- What the applicant typed about where they shop: a hint, never ownership.
  dealer_hint text,
  created_at timestamp NOT NULL,
  closed_at timestamp,
  outcome_note text,
  resume_token_hash text,
  resume_expires_at timestamptz,
  resume_progress text,
  version integer NOT NULL DEFAULT 0,
  CHECK (status = 'draft' OR reference IS NOT NULL),
  CHECK ((status = 'closed') = (closed_at IS NOT NULL))
);

-- ================================================================ platform: servicing

-- A borrower with at least one funded loan: who /customer signs in.
CREATE TABLE customer (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  applicant_id text NOT NULL UNIQUE REFERENCES applicant(id),
  account_id text UNIQUE,
  first_name text NOT NULL,
  last_name text NOT NULL,
  email text NOT NULL UNIQUE,
  phone text NOT NULL,
  street text NOT NULL,
  city text NOT NULL,
  state text NOT NULL CHECK (state ~ '^[A-Z]{2}$'),
  zip text NOT NULL CHECK (zip ~ '^[0-9]{5}$'),
  paperless boolean NOT NULL DEFAULT true,
  preferred_contact text NOT NULL CHECK (preferred_contact IN ('email', 'phone', 'text')),
  customer_since date NOT NULL,
  version integer NOT NULL DEFAULT 0
);

CREATE TABLE loan (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  loan_number text NOT NULL UNIQUE,
  application_id text NOT NULL UNIQUE REFERENCES loan_application(id),
  customer_id integer NOT NULL REFERENCES customer(id),
  dealer_id text NOT NULL REFERENCES dealer(id),
  -- Said on the loan itself so /customer needs no read of a dealer's inventory.
  vehicle_description text NOT NULL,
  vin text NOT NULL,
  principal numeric(12,2) NOT NULL CHECK (principal > 0),
  apr numeric(6,3) NOT NULL CHECK (apr >= 0),
  term_months integer NOT NULL CHECK (term_months BETWEEN 12 AND 96),
  payment_amount numeric(12,2) NOT NULL CHECK (payment_amount > 0),
  funded_on date NOT NULL,
  first_due_on date NOT NULL,
  maturity_on date NOT NULL,
  principal_balance numeric(12,2) NOT NULL CHECK (principal_balance >= 0),
  interest_paid numeric(12,2) NOT NULL DEFAULT 0,
  next_due_on date,
  amount_due numeric(12,2) NOT NULL DEFAULT 0,
  days_past_due integer NOT NULL DEFAULT 0 CHECK (days_past_due >= 0),
  status text NOT NULL CHECK (status IN ('current', 'past_due', 'delinquent', 'charged_off', 'paid_off')),
  paid_off_on date,
  charged_off_on date,
  version integer NOT NULL DEFAULT 0,
  UNIQUE (customer_id, id),
  CHECK ((status = 'paid_off') = (paid_off_on IS NOT NULL)),
  CHECK ((status = 'charged_off') = (charged_off_on IS NOT NULL))
);
CREATE INDEX loan_status ON loan (status, days_past_due);

-- The schedule the contract promised: one row per installment.
CREATE TABLE installment (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id integer NOT NULL,
  loan_id integer NOT NULL REFERENCES loan(id),
  number integer NOT NULL CHECK (number > 0),
  due_on date NOT NULL,
  amount numeric(12,2) NOT NULL,
  principal numeric(12,2) NOT NULL,
  interest numeric(12,2) NOT NULL,
  status text NOT NULL CHECK (status IN ('paid', 'past_due', 'due', 'upcoming', 'closed')),
  paid_on date,
  FOREIGN KEY (customer_id, loan_id) REFERENCES loan(customer_id, id),
  UNIQUE (loan_id, number),
  CHECK ((status = 'paid') = (paid_on IS NOT NULL))
);

CREATE TABLE payment (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id integer NOT NULL,
  loan_id integer NOT NULL REFERENCES loan(id),
  reference text NOT NULL UNIQUE,
  received_on date NOT NULL,
  amount numeric(12,2) NOT NULL CHECK (amount > 0),
  principal numeric(12,2) NOT NULL DEFAULT 0,
  interest numeric(12,2) NOT NULL DEFAULT 0,
  late_fee numeric(12,2) NOT NULL DEFAULT 0,
  method text NOT NULL CHECK (method IN ('autopay', 'ach', 'card', 'check')),
  channel text NOT NULL CHECK (channel IN ('customer_portal', 'autopay', 'phone', 'mail')),
  status text NOT NULL CHECK (status IN ('pending', 'posted', 'returned')),
  returned_reason text,
  FOREIGN KEY (customer_id, loan_id) REFERENCES loan(customer_id, id),
  CHECK ((status = 'returned') = (returned_reason IS NOT NULL))
);
CREATE INDEX payment_loan ON payment (loan_id, received_on);

CREATE TABLE autopay (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id integer NOT NULL,
  loan_id integer NOT NULL REFERENCES loan(id),
  bank_name text NOT NULL,
  account_type text NOT NULL CHECK (account_type IN ('checking', 'savings')),
  account_last4 text NOT NULL CHECK (account_last4 ~ '^[0-9]{4}$'),
  draft_day integer NOT NULL CHECK (draft_day BETWEEN 1 AND 28),
  status text NOT NULL CHECK (status IN ('active', 'paused', 'cancelled')),
  enrolled_on date NOT NULL,
  cancelled_on date,
  version integer NOT NULL DEFAULT 0,
  FOREIGN KEY (customer_id, loan_id) REFERENCES loan(customer_id, id),
  CHECK ((status = 'cancelled') = (cancelled_on IS NOT NULL))
);
CREATE UNIQUE INDEX autopay_one_live ON autopay (loan_id) WHERE status <> 'cancelled';

CREATE TABLE payoff_quote (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id integer NOT NULL,
  loan_id integer NOT NULL REFERENCES loan(id),
  requested_on date NOT NULL,
  good_through date NOT NULL,
  amount numeric(12,2) NOT NULL CHECK (amount >= 0),
  per_diem numeric(12,2) NOT NULL CHECK (per_diem >= 0),
  requested_via text NOT NULL CHECK (requested_via IN ('customer_portal', 'phone', 'dealer')),
  status text NOT NULL CHECK (status IN ('issued', 'expired', 'paid')),
  version integer NOT NULL DEFAULT 0,
  FOREIGN KEY (customer_id, loan_id) REFERENCES loan(customer_id, id),
  CHECK (good_through >= requested_on)
);

-- What a borrower downloads: a file resource, one small PDF a row.
CREATE TABLE loan_document (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id integer NOT NULL,
  loan_id integer NOT NULL REFERENCES loan(id),
  kind text NOT NULL CHECK (kind IN ('contract', 'truth_in_lending', 'welcome_letter', 'statement', 'payoff_letter', 'title_release')),
  title text NOT NULL,
  issued_on date NOT NULL,
  file_name text NOT NULL,
  content_type text NOT NULL,
  byte_size integer NOT NULL,
  data bytea NOT NULL,
  FOREIGN KEY (customer_id, loan_id) REFERENCES loan(customer_id, id)
);

-- Servicing and collections' own record of a borrower; never the borrower's.
CREATE TABLE servicing_note (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  loan_id integer NOT NULL REFERENCES loan(id),
  author_id integer NOT NULL REFERENCES lender_user(id),
  created_at timestamp NOT NULL,
  kind text NOT NULL CHECK (kind IN ('call', 'email', 'promise_to_pay', 'hardship', 'note')),
  body text NOT NULL,
  promise_amount numeric(12,2),
  promise_on date,
  CHECK ((kind = 'promise_to_pay') = (promise_on IS NOT NULL))
);

-- ================================================================ platform: the marketplace

-- A soft pre-qualification: no bureau pull, an estimate of what an advertised
-- program could lend. Sent to a dealer, it becomes that dealer's lead.
CREATE TABLE prequalification (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  reference text NOT NULL UNIQUE,
  first_name text NOT NULL,
  last_name text NOT NULL,
  email text NOT NULL,
  phone text,
  zip text NOT NULL CHECK (zip ~ '^[0-9]{5}$'),
  credit_band text NOT NULL CHECK (credit_band IN ('excellent', 'good', 'fair', 'rebuilding', 'unsure')),
  monthly_income numeric(12,2) NOT NULL CHECK (monthly_income >= 0),
  desired_payment numeric(12,2) NOT NULL CHECK (desired_payment >= 0),
  vehicle_id text REFERENCES vehicle(id),
  program_id integer REFERENCES program(id),
  estimated_amount numeric(12,2),
  estimated_apr numeric(6,3),
  status text NOT NULL CHECK (status IN ('new', 'matched', 'sent_to_dealer', 'no_match', 'expired')),
  lead_id text REFERENCES lead(id),
  -- The customer's /marketplace account, when they were signed in.
  account_id text,
  created_at timestamp NOT NULL,
  version integer NOT NULL DEFAULT 0,
  CHECK ((status = 'sent_to_dealer') = (lead_id IS NOT NULL))
);

-- A signed-in customer's shortlist on the marketplace.
CREATE TABLE saved_vehicle (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id text NOT NULL,
  vehicle_id text NOT NULL REFERENCES vehicle(id),
  status text NOT NULL CHECK (status IN ('saved', 'archived')),
  saved_at timestamp NOT NULL,
  note text,
  version integer NOT NULL DEFAULT 0,
  UNIQUE (account_id, vehicle_id)
);
